from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy

class OptimalTouringCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        sites_data = message.message[0].data[0]
        visited_sites = self.find_optimal_tour(sites_data)
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=visited_sites, type='custom')]
        )

    def find_optimal_tour(self, sites_data):
        def manhattan_distance(site1, site2):
            return abs(site1['avenue'] - site2['avenue']) + abs(site1['street'] - site2['street'])

        def backtrack(current_time, current_site, remaining_sites, current_value, current_path):
            nonlocal max_value, best_path
            if current_value > max_value:
                max_value = current_value
                best_path = current_path.copy()

            for next_site_id in remaining_sites:
                next_site = sites_data[next_site_id]
                travel_time = manhattan_distance(current_site, next_site)
                new_time = current_time + travel_time + next_site['desiredtime'] / 60

                if new_time <= next_site['endhour'] and new_time >= next_site['beginhour']:
                    remaining_sites.remove(next_site_id)
                    current_path.append(next_site_id)
                    backtrack(new_time, next_site, remaining_sites, current_value + next_site['value'], current_path)
                    current_path.pop()
                    remaining_sites.add(next_site_id)

        max_value = 0
        best_path = []
        for start_site_id in sites_data:
            start_site = sites_data[start_site_id]
            remaining_sites = set(sites_data.keys()) - {start_site_id}
            backtrack(start_site['beginhour'], start_site, remaining_sites, 0, [start_site_id])

        return best_path

